import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;
import java.net.URI;
import java.net.URISyntaxException;
import java.util.Arrays;
import java.util.List;

public class SecureProxy {
    private static final List<String> ALLOWED_SCHEMES = Arrays.asList("http", "https");

    public void fetchContent(String targetUrl) throws IOException {
        try {
            // Properly validate the input URI before processing
            URI uri = new URI(targetUrl);

            // Ensure the scheme is in the allowed list
            if (!ALLOWED_SCHEMES.contains(uri.getScheme().toLowerCase())) {
                throw new SecurityException("Invalid scheme");
            }

            // Additional validation for host/IP range could be added here

            URL url = uri.toURL();
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");
            int status = conn.getResponseCode();
            System.out.println(status);

            conn.disconnect();
        } catch (URISyntaxException e) {
            throw new IllegalArgumentException("Invalid URL provided", e);
        }
    }
}
